/*Insert Manufacturers*/

INSERT INTO [dbo].[MeasurementDevicesManufacturers]
           ([Name]
           ,[CreatedDate]
           ,[IsDeleted]
           ,[UpdateUserID])

SELECT DISTINCT t.Manufacturer, GETDATE(),0,0
FROM #test as t
LEFT JOIN [dbo].[MeasurementDevicesManufacturers] as mf ON t.Manufacturer = mf.Name
WHERE mf.Name IS NULL AND t.Manufacturer IS NOT NULL

/*Insert data for measurment devices for temperature and humidity*/

DECLARE @SensorId INT, @LoggerId INT, @MainCategoryId INT

SELECT @SensorId = Id
FROM [dbo].[MeasurementDevicesMainClasses]
WHERE NameEnglish='Sensor'

SELECT @LoggerId = Id
FROM [dbo].[MeasurementDevicesMainClasses]
WHERE NameEnglish='Data logger'


SELECT @MainCategoryId = ID
FROM [dbo].[MainCategories] 
WHERE MainCategoryName = N'טמפרטורה ולחות'

INSERT INTO [dbo].[MeasurementDevices]
           ([MabaID]
           ,[Description]
           ,[ManufacturerId]
           ,[Model]
           ,[SerialNumber]
           ,[NextCalibration]
           ,[Note]
           ,[CalibrationDate]
           ,[MeasurementId]
           ,[MainClassId]
           ,[SubClassId]
           ,[ExtraCalTools]
           ,[MainCategoryId]
           ,[UnitId]
           ,[CalibratorId]
           ,[ReportNumber]
           ,[WorkRangeUnitId]
           ,[WorkRangeMin]
           ,[WorkRangeMax]
           ,[DefaultPrecision]
           ,[HighestPrecision]
           ,[CreateDate]
           ,[RemoveDate]
           ,[UpdateDate]
           ,[UpdateUserID]
           ,[AllowMinOOR]
           ,[AllowMaxOOR]
           ,[IsDeleted]
           ,[Resolution]
           ,[MeasurementDeviceSourceId]
           ,[MeasurementDeviceStatusId]
           ,[IP]
           ,[Connection]
           ,[SecondaryCategoryId])
SELECT
           t.[ID]
           ,t.[DeviceDescription]
           ,mnf.[ID]
           ,t.Model
           ,t.ManufacturerSerialNumber
           ,TRY_CAST(t.NextCalibrationDate AS DATETIME2(0))
           ,t.Notes
           ,NULL
           ,NULL
           ,CASE WHEN t.Subdepartment IN (N'2W','4W') THEN @SensorId ELSE @LoggerId END
           ,NULL
           ,NULL
           ,@MainCategoryId
           ,NULL
           ,NULL
           ,t.LastCalibrationReport
           ,NULL
           ,NULL
           ,NULL
           ,NULL
           ,NULL
           ,GETDATE()
           ,NULL
           ,NULL
           ,NULL
           ,NULL
           ,NULL
           ,0
           ,0
           ,NULL
           ,CASE 
                WHEN TRY_CAST(t.NextCalibrationDate AS DATETIME2(0)) <= GETDATE() THEN
                (SELECT TOP 1 s.StatusId
                  FROM [Calibrator].[dbo].[Statuses] as s
                  JOIN [Calibrator].[dbo].[StatusesCategories] as sc ON s.StatusCategoryId = sc.StatusCategoryId
                  WHERE sc.StatusDescriptionENG = N'MeasurementDeviceStatus' AND s.StatusDescriptionENG = N'NotCalibrated')
                ELSE (SELECT TOP 1 s.StatusId
                      FROM [Calibrator].[dbo].[Statuses] as s
                      JOIN [Calibrator].[dbo].[StatusesCategories] as sc ON s.StatusCategoryId = sc.StatusCategoryId
                      WHERE sc.StatusDescriptionENG = N'MeasurementDeviceStatus' AND s.StatusDescriptionENG = N'Available')
            END
           ,NULL
           ,t.Subdepartment
           ,NULL
FROM #test as t
LEFT JOIN [dbo].[MeasurementDevicesManufacturers] as mnf ON t.Manufacturer = mnf.Name
LEFT JOIN [dbo].[MeasurementDevices] as md ON t.[ID] = md.MabaID
WHERE t.[Department] IN (N'לחות',N'טמפרטורה')  AND md.MabaID IS NULL


UPDATE [dbo].[MeasurementDevices]
SET SerialNumber = REVERSE(SerialNumber)
WHERE  PATINDEX(N'%[' + NCHAR(0x0590) + N'-' + NCHAR(0x05FF) + N']%', SerialNumber COLLATE Latin1_General_100_BIN2) > 0